usage_example:
```hcl
resource "betterado_release_definition" "example" {
  name       = "my-release"
  project_id = var.project_id

  environment {
    name = "Staging"
    rank = 1

    deploy_phase {
      name       = "Agentless"
      rank       = 1
      phase_type = "runOnServer"
    }

    retention_policy {
      days_to_keep     = 30
      releases_to_keep = 3
      retain_build     = true
    }

    pre_deploy_approval {
      approver {
        id           = "00000000-0000-0000-0000-000000000000"
        is_automated = true
        rank         = 1
      }
      approval_options {
        timeout_in_minutes              = 1440
        execution_order                 = "beforeGates"
        release_creator_can_be_approver = false
      }
    }

    post_deploy_approval {
      approver {
        id           = "00000000-0000-0000-0000-000000000000"
        is_automated = true
        rank         = 1
      }
    }

    pre_deployment_gates {
      gates_options {
        is_enabled               = true
        timeout                  = 600
        sampling_interval        = 60
        stabilization_time       = 0
        minimum_success_duration = 0
      }
      gate {
        task {
          name    = "Query Work Items"
          task_id = "f1e4b0e6-017e-4819-8a48-ef19ae96e289"
          version = "0.*"
          enabled = true
          inputs = {
            queryId = var.gate_query_id
          }
        }
      }
    }
  }
}
```
